    return new NextResponse(workbook, {
      status: 200,
      headers: {
        'Content-Type':
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': 'attachment; filename="gestion-recibos.xlsx"',
        'Cache-Control': 'no-store',
      },
